const social = [['YouTube','https://www.youtube.com/@anderzilla-tv'],['TikTok','https://www.tiktok.com/@anderzilla'],['Instagram','https://www.instagram.com/anderzilla/'],['Twitch','https://www.twitch.tv/anderzillacwb'],['Kick','https://kick.com/anderzilla']];
