const external = (url,label,classes='text-link') => `<a class="${classes}" href="${url}" target="_blank" rel="noopener noreferrer">${label}</a>`;
const art = kind => kind==='game' ? '<div class="game-art" aria-hidden="true"><div class="controller"></div></div>' : kind==='chip' ? '<div class="circuit-art" aria-hidden="true"><div class="chip">AI</div></div>' : kind==='dev' ? '<div class="story-visual visual-dev" aria-hidden="true"><div class="terminal">&gt; build something<br><span>_ just for fun.</span></div></div>' : kind==='gadget' ? '<div class="story-visual visual-gadgets" aria-hidden="true"><div class="keyboard"></div></div>' : '<div class="story-visual visual-cloud" aria-hidden="true"><div class="cloud-mark">{ db }</div></div>';
function comparisons(t){return [['hosting','Railway vs Render','railway-vs-render'],['database','Neon vs Supabase','neon-vs-supabase'],['aiEditor','Cursor vs Copilot','cursor-vs-copilot']].map(([category,title,slug])=>`<a class="compare-row" href="https://anderzilla.com/stackpick/${slug}" target="_blank" rel="noopener noreferrer"><div><span>${t[category]}</span><strong>${title}</strong></div><b aria-hidden="true">↗</b></a>`).join('')}
function home(t){return `<div class="wrap"><div class="intro-line"><span>${t.line}</span><span>${t.lineRight}</span></div><h1 class="masthead">${t.title}</h1><div class="hero-grid"><a class="cover" href="https://anderzilla.com/stackpick/cursor-vs-copilot" target="_blank" rel="noopener noreferrer" aria-label="${t.coverLink}: Cursor vs Copilot">${art('chip')}<p class="eyebrow"><span class="pill">STACKPICK</span>${t.feature}</p><h2>${t.coverTitle}</h2><div class="cover-bottom"><span>${t.coverMeta}</span><span class="circle-arrow" aria-hidden="true">↗</span></div></a><section class="side-feature"><img class="ghost-feature" src="assets/anderzilla-ghost.png" width="1024" height="1024" alt="AnderZilla Ghost: personagem com boné vermelho, rosto de caveira amarelo e fundo azul"><div class="side-copy"><p class="eyebrow">${t.gaming}</p><h2>${t.gameTitle}</h2><p>${t.gameText}</p><a class="text-link" href="#channels">${t.gameCta}</a></div></section></div><div class="topic-strip" role="group" aria-label="${t.filterTitle}"><strong>${t.filterTitle}</strong>${[['all',t.all],['ai','IA / AI'],['games','Games'],['gadgets',t.gadgets],['dev','Dev']].map(([id,label])=>`<button class="filter" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><section aria-labelledby="explore-title"><div class="section-heading"><div><h2 id="explore-title">${t.latest}</h2><p>${t.latestSub}</p></div><a class="text-link" href="#article">${t.viewFormat}</a></div><div id="stories" aria-live="polite">${stories(t)}</div></section><section class="stack-section"><div><p class="eyebrow">STACKPICK / ${t.explore}</p><h2>${t.stackTitle}</h2><p>${t.stackDesc}</p><a class="text-link" href="#stackpick">${t.stackCta}</a></div><div>${comparisons(t)}</div></section><div class="bottom-grid"><section class="about-panel"><img class="about-avatar" src="assets/anderzilla-ghost.png" width="96" height="96" alt="AnderZilla Ghost"><p class="eyebrow">${t.aboutKicker}</p><h2>${t.aboutTitle}</h2><p>${t.aboutText}</p><a class="text-link" href="#channels">${t.aboutCta}</a></section><section class="product-panel"><p class="eyebrow">${t.ownProduct}</p><h2>ForgeKit <span aria-hidden="true">↗</span></h2><p>${t.productText}</p>${external('https://anderzilla.gumroad.com/l/edkel',t.productCta,'button')}<p class="note-small">${t.productNote}</p></section></div><section class="sponsor-band"><div><h2>${t.sponsorTitle}</h2><p>${t.sponsorText}</p></div><a class="button" href="#sponsor">${t.sponsorCta}</a></section></div>`}
function stories(t){if(filter==='games'||filter==='ai')return `<div class="empty-filter">${filter==='games'?t.noGames:t.noAi}<br><br><a class="text-link" href="${filter==='games'?'#channels':'#article'}">${filter==='games'?t.gameCta:t.viewFormat}</a></div>`;const cards=[['dev','dev',t.hosting,t.published,t.storyOne,t.storyOneText,'https://anderzilla.com/stackpick/railway-vs-render'],['gadgets','gadget',t.gadgets,t.proposed,t.storyTwo,t.storyTwoText,'#article'],['dev','cloud',t.database,t.published,t.storyThree,t.storyThreeText,'https://anderzilla.com/stackpick/neon-vs-supabase']];return `<div class="card-grid">${cards.filter(x=>filter==='all'||x[0]===filter).map(([cat,visual,label,status,title,description,url])=>`<article class="story">${art(visual)}<p class="eyebrow">${label}<span class="status">${status}</span></p><h3><a href="${url}" ${url.startsWith('https')?'target="_blank" rel="noopener noreferrer"':''}>${title}</a></h3><p>${description}</p><div class="story-meta">AnderZilla · ${cat==='gadgets'?t.proposalCta:t.read}</div></article>`).join('')}</div>`}
const pageStart=t=>`<div class="wrap subpage"><a class="back" href="#home">${t.back}</a>`;
function article(t){return `${pageStart(t)}<p class="eyebrow">IA / AI · ANDERZILLA</p><h1 class="page-title">${t.articleTitle}</h1><p class="lede">${t.articleLede}</p><div class="notice">${t.articleNotice}</div><div class="article-layout"><article class="article-body"><h2>${t.articleH1}</h2><p>${t.articleP1}</p><h2>${t.articleH2}</h2><ul>${t.articleList.map(item=>`<li>${item}</li>`).join('')}</ul><h2>${t.articleH3}</h2><p>${t.articleP2}</p><h2>${t.articleNext}</h2><p>${t.articleNextText}</p>${external('https://anderzilla.com/stackpick/cursor-vs-copilot',t.existing)}</article><aside class="article-aside"><strong>${t.articleAside}</strong><p>${t.articleAsideText}</p><a href="#stackpick">StackPick →</a><a href="#sponsor">${t.sponsor} →</a></aside></div></div>`}
function stackpick(t){return `${pageStart(t)}<p class="eyebrow">STACKPICK</p><h1 class="page-title">${t.stackPageTitle}</h1><p class="lede">${t.stackPageLede}</p><div class="notice">${t.stackNotice}</div><div class="table-scroll"><table><thead><tr><th scope="col">${t.criterion}</th><th scope="col">${t.question}</th><th scope="col">${t.evidence}</th></tr></thead><tbody>${t.tableRows.map(row=>`<tr><th scope="row">${row[0]}</th><td>${row[1]}</td><td>${row[2]}</td></tr>`).join('')}</tbody></table></div><section class="stack-section"><div><p class="eyebrow">STACKPICK</p><h2>${t.existingComparisons}</h2><p>${t.coverMeta}</p></div><div>${comparisons(t)}</div></section></div>`}
function channels(t){return `${pageStart(t)}<p class="eyebrow">@ANDERZILLA</p><h1 class="page-title">${t.channelTitle}</h1><p class="lede">${t.channelLede}</p><div class="channel-grid">${social.map(([name,url],i)=>`<section class="channel-card"><p class="eyebrow">0${i+1} / ${name.toUpperCase()}</p><h2>${name}</h2><p>${t.channelTexts[i]}</p>${external(url,t.visit)}</section>`).join('')}</div></div>`}
function sponsor(t){return `${pageStart(t)}<p class="eyebrow">ANDERZILLA / ${t.sponsor}</p><h1 class="page-title">${t.sponsorPageTitle}</h1><p class="lede">${t.sponsorLede}</p><div class="notice">${t.sponsorNotice}</div><div class="offer-grid">${t.offers.map(([title,text],i)=>`<section class="offer"><p class="eyebrow">0${i+1}</p><h2>${title}</h2><p>${text}</p></section>`).join('')}</div><h2>${t.briefTitle}</h2><p class="note-small">${t.briefText}</p><div class="brief-options" role="group" aria-label="${t.briefFormat}">${t.offers.map(([title],i)=>`<button class="filter" data-format="${i}" aria-pressed="${format===i}">${title}</button>`).join('')}</div><div class="brief-output" id="brief-output">${brief(t)}</div><p><button class="button" id="download">${t.download}</button></p><p class="status-message" role="status" id="download-status"></p></div>`}
function brief(t){return `AnderZilla — ${t.briefTitle}\n${t.briefFormat}: ${t.offers[format][0]}\n\n${t.briefLines}`}
function render({focus=false}={}){const t=copy[language];document.querySelector('.site-header nav').setAttribute('aria-label',language==='pt'?'Principal':'Main');document.documentElement.lang=language==='pt'?'pt-BR':'en';document.title=`AnderZilla — ${language==='pt'?'estudo editorial':'editorial study'}`;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t[el.dataset.i18n]);document.querySelectorAll('[data-language]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.language===language)));const route=location.hash.slice(1)||'home';const main=document.getElementById('main');main.innerHTML=({home,article,stackpick,channels,sponsor}[route]||home)(t);document.querySelectorAll('.site-header nav a').forEach(el=>{if(el.hash===`#${route}`)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});if(focus){main.focus({preventScroll:true});window.scrollTo(0,0)}}
document.addEventListener('click',event=>{const langButton=event.target.closest('[data-language]');if(langButton){language=langButton.dataset.language;const url=new URL(location.href);url.searchParams.set('lang',language);history.replaceState(null,'',url);render();return}const filterButton=event.target.closest('[data-filter]');if(filterButton){filter=filterButton.dataset.filter;document.querySelectorAll('[data-filter]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.filter===filter)));document.getElementById('stories').innerHTML=stories(copy[language]);return}const formatButton=event.target.closest('[data-format]');if(formatButton){format=Number(formatButton.dataset.format);document.querySelectorAll('[data-format]').forEach(el=>el.setAttribute('aria-pressed',String(Number(el.dataset.format)===format)));document.getElementById('brief-output').textContent=brief(copy[language]);return}if(event.target.closest('#download')){const blob=new Blob([brief(copy[language])],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`anderzilla-brief-${language}.txt`;anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('download-status').textContent=copy[language].downloaded}});
window.addEventListener('hashchange',()=>render({focus:true}));render();
